// ---------- a tiny stand-in for the browser's DOM, enough for renderConnections ----------
class FakeNode {
  constructor(tag, ns = null) { this.tagName = String(tag).toUpperCase(); this.ns = ns; this.attributes = {}; this.children = []; this.listeners = {}; this.dataset = {}; this.className = ''; this.innerHTML = ''; this.text = ''; }
  setAttribute(k, v) { this.attributes[k] = String(v); }
  getAttribute(k) { return k in this.attributes ? this.attributes[k] : null; }
  append(...kids) { for (const k of kids) this.children.push(k instanceof FakeNode ? k : new FakeText(String(k))); }
  replaceChildren(...kids) { this.children = []; this.append(...kids); }
  addEventListener(type, fn) { (this.listeners[type] ||= []).push(fn); }
  fire(type, target = this) { for (const fn of this.listeners[type] || []) fn({ target, preventDefault() {}, stopPropagation() {} }); }
  get textContent() { return this.text + this.children.map((c) => c.textContent).join(''); }
  set textContent(v) { this.text = String(v); this.children = []; }
  all(pred, out = []) { if (pred(this)) out.push(this); for (const c of this.children) c.all(pred, out); return out; }
  querySelector(sel) { return this.all((n) => sel.startsWith('#') && n.attributes.id === sel.slice(1))[0] || null; }
}
class FakeText extends FakeNode { constructor(s) { super('#text'); this.text = s; } }
globalThis.Node = FakeNode;
globalThis.document = { createElement: (t) => new FakeNode(t), createElementNS: (ns, t) => new FakeNode(t, ns), createTextNode: (s) => new FakeText(s) };

