test('renderConnections: three groups, the app\'s chip classes, Earth demos off, callbacks fire', () => {
  const calls = [];
  const host = new FakeNode('div');
  renderConnections(host, { state: {}, onToggle: (id, on) => calls.push(['toggle', id, on]), onImport: (f) => calls.push(['import', f.name]), onConnect: (k) => calls.push(['connect', k]) });
  const rows = host.all((n) => n.attributes['data-conn']);
  assert.equal(rows.length, CONNECTIONS.length);
  const chipOf = (id) => rows.find((r) => r.attributes['data-conn'] === id).all((n) => /\bchip\b/.test(n.className))[0].className;
  assert.equal(chipOf('fhir-export'), 'chip neutral');
  assert.equal(chipOf('link-earth'), 'chip stale');
  assert.equal(chipOf('everywear'), 'chip off');
  assert.equal(host.all((n) => n.tagName === 'DETAILS').length, 2, 'simulated and planned are folded');
  const sw1 = host.all((n) => n.attributes.id === 'conn-isslive')[0];
  assert.equal(sw1.attributes.checked, undefined, 'ISSLive starts off');
  assert.equal(host.all((n) => n.attributes.id === 'conn-spaceweather')[0].attributes.checked, undefined, 'space weather starts off');
  sw1.fire('change', { checked: true });
  const thermo = host.all((n) => n.tagName === 'BUTTON' && n.textContent === 'Thermometer')[0];
  thermo.fire('click');
  const file = host.all((n) => n.tagName === 'INPUT' && n.attributes.type === 'file')[0];
  file.fire('change', { files: [{ name: 'shirt.csv' }], value: 'x' });
  assert.deepEqual(calls, [['toggle', 'isslive', true], ['connect', 'thermometer'], ['import', 'shirt.csv']]);
  assert.ok(host.all((n) => n.className === 'tip-btn' && n.dataset.tip === 'c:dicom').length === 1, 'each row has its ? key');
});

