// ---------- Bluetooth ----------
const hex = (s) => s.split(' ').map((b) => parseInt(b, 16));

test('BLE numbers: the specification examples 36.4 = FLOAT 0xFF00016C and 114 = SFLOAT 0x0072', () => {
  assert.deepEqual(ble.decodeFloat(0xff00016c), { value: 36.4, special: null });
  assert.deepEqual(ble.decodeSfloat(0x0072), { value: 114, special: null });
  assert.deepEqual(ble.decodeSfloat(0xffff), { value: -0.1, special: null });
  assert.deepEqual(ble.decodeSfloat(0xf098), { value: 15.2, special: null });
  for (const [raw, name] of [[0x07ff, 'NaN'], [0x0800, 'NRes'], [0x07fe, '+INF'], [0x0802, '-INF'], [0x0801, 'reserved']]) assert.deepEqual(ble.decodeSfloat(raw), { value: null, special: name });
  for (const [raw, name] of [[0x007fffff, 'NaN'], [0x00800000, 'NRes'], [0x007ffffe, '+INF'], [0x00800002, '-INF']]) assert.deepEqual(ble.decodeFloat(raw), { value: null, special: name });
});

test('BLE thermometer: Celsius, Fahrenheit, time stamp and type, not a number', () => {
  assert.equal(ble.parseTemperature(hex('00 6C 01 00 FF')).celsius, 36.4);
  const f = ble.parseTemperature(hex('01 DA 03 00 FF')); // 98.6 F
  assert.equal(f.celsius, 37);
  assert.deepEqual(f.sent, { value: 98.6, unit: '°F' });
  const full = ble.parseTemperature(hex('06 6C 01 00 FF EA 07 0B 0F 00 28 05 02'));
  assert.equal(full.deviceTime.text, '2026-11-15 00:40:05');
  assert.equal(full.typeName, 'body (general)');
  const nan = ble.parseTemperature(hex('00 FF FF 7F 00'));
  assert.equal(nan.celsius, null);
  assert.equal(nan.special, 'NaN');
  assert.throws(() => ble.parseTemperature(hex('02 6C 01 00 FF EA')), RangeError);
});

test('BLE blood pressure: mmHg, kPa turned into mmHg, pulse and the cuff\'s own warnings', () => {
  const mm = ble.parseBloodPressure(hex('00 72 00 4C 00 59 00'));
  assert.deepEqual([mm.sys, mm.dia, mm.map, mm.sent.unit], [114, 76, 89, 'mmHg']);
  const kpa = ble.parseBloodPressure(hex('01 98 F0 65 F0 76 F0'));
  assert.deepEqual([kpa.sys, kpa.dia, kpa.sent.unit], [114, 75.8, 'kPa']);
  const more = ble.parseBloodPressure(hex('14 72 00 4C 00 59 00 48 00 06 00'));
  assert.equal(more.pulse, 72);
  assert.equal(more.status.cuffTooLoose, true);
  assert.equal(more.status.irregularPulse, true);
  assert.equal(more.status.bodyMovement, false);
  assert.equal(more.status.pulseRange, 'within');
  const ts = ble.parseBloodPressure(hex('0A 72 00 4C 00 59 00 EA 07 0B 0F 06 1E 00 01'));
  assert.equal(ts.deviceTime.text, '2026-11-15 06:30:00');
  assert.equal(ts.userId, 1);
});

test('BLE pulse oximeter: spot-check and continuous, demonstration data refused', () => {
  const spot = ble.parsePlxSpotCheck(hex('00 62 00 48 00'));
  assert.deepEqual([spot.spo2, spot.pulse, spot.quality.ok], [98, 72, true]);
  const demo = ble.parsePlxContinuous(hex('04 61 00 46 00 00 04'));
  assert.equal(demo.quality.ok, false);
  assert.deepEqual(demo.measurementStatus, ['data for demonstration']);
  const all = ble.parsePlxContinuous(hex('1B 61 00 46 00 60 00 47 00 61 00 46 00 20 00 00 19 F0'));
  assert.deepEqual(all.fast, { spo2: 96, pulse: 71 });
  assert.deepEqual(all.slow, { spo2: 97, pulse: 70 });
  assert.deepEqual(all.deviceStatus, ['low perfusion detected']);
  assert.equal(all.pai, 2.5);
  assert.equal(all.quality.ok, true);
  const noFinger = ble.parsePlxContinuous(hex('00 FF 07 FF 07'));
  assert.equal(noFinger.quality.ok, false);
});

test('BLE heart rate: 8 and 16 bit values, sensor contact, RR intervals', () => {
  assert.equal(ble.parseHeartRate(hex('00 48')).bpm, 72);
  assert.equal(ble.parseHeartRate(hex('01 2C 01')).bpm, 300);
  assert.equal(ble.parseHeartRate(hex('06 48')).contact, true);
  assert.equal(ble.parseHeartRate(hex('04 48')).contact, false);
  assert.equal(ble.parseHeartRate(hex('00 48')).contact, null);
  assert.deepEqual(ble.parseHeartRate(hex('18 3C 10 00 00 04 00 02')).rr, [1000, 500]); // energy skipped, RR 1024 and 512
});

test('BLE readings: the program\'s shape, plausibility limits, what the device marks as not real', () => {
  const t = '2026-11-15T01:00:00.000Z';
  const bp = ble.toReadings('blood-pressure', ble.parseBloodPressure(hex('14 72 00 4C 00 59 00 48 00 00 00')), t);
  assert.deepEqual(bp.readings, [
    { source: 'ble-bp', indicator: 'bp', value: { sys: 114, dia: 76 }, unit: 'mmHg', time: t },
    { source: 'ble-bp', indicator: 'pulse', value: 72, unit: 'bpm', time: t },
  ]);
  assert.equal(ble.toReadings('thermometer', ble.parseTemperature(hex('00 6C 01 00 FF')), t).readings[0].indicator, 'temp');
  const hot = ble.toReadings('thermometer', ble.parseTemperature(hex('00 C2 01 00 FF')), t); // 45.0 C: outside 30 to 44
  assert.equal(hot.readings.length, 0);
  assert.match(hot.skipped[0].reason, /plausibility/);
  assert.equal(ble.toReadings('pulse-oximeter', ble.parsePlxContinuous(hex('04 61 00 46 00 00 04')), t).readings.length, 0);
});

function fakeBluetooth({ refuse = null, has = null } = {}) {
  const chars = {};
  const device = {
    name: 'Test cuff', listeners: {},
    addEventListener(type, fn) { this.listeners[type] = fn; },
    gatt: {
      connected: true,
      disconnect() { this.connected = false; device.listeners.gattserverdisconnected && device.listeners.gattserverdisconnected(); },
      async connect() {
        return { async getPrimaryService(name) {
          return { async getCharacteristic(c) {
            if (has && !has.includes(c)) throw new Error('not found');
            chars[c] = { listeners: [], addEventListener(type, fn) { this.listeners.push(fn); }, async startNotifications() { this.started = true; }, send(bytes) { for (const fn of this.listeners) fn({ target: { value: new DataView(Uint8Array.from(bytes).buffer) } }); } };
            chars[c].service = name;
            return chars[c];
          } };
        } };
      },
    },
  };
  return { chars, device, async requestDevice(opts) { this.asked = opts; if (refuse) { const e = new Error('no'); e.name = refuse; throw e; } return device; } };
}

test('connectHealthDevice: the browser chooser, notifications, one reading a minute for a stream', async () => {
  const bt = fakeBluetooth({ has: ['plx_continuous_measurement'] });
  let clock = Date.UTC(2026, 10, 15, 1, 0, 0);
  const kept = [];
  const live = [];
  const handle = await ble.connectHealthDevice('pulse-oximeter', (r) => kept.push(r), { bluetooth: bt, now: () => new Date(clock), onLive: (p) => live.push(p) });
  assert.deepEqual(bt.asked, { filters: [{ services: ['pulse_oximeter'] }] });
  assert.deepEqual(handle.characteristics, ['plx_continuous_measurement']);
  const ch = bt.chars.plx_continuous_measurement;
  assert.equal(ch.started, true);
  ch.send(hex('00 61 00 46 00'));
  clock += 1000;
  ch.send(hex('00 62 00 47 00'));
  clock += 60000;
  ch.send(hex('00 60 00 48 00'));
  assert.equal(live.length, 3);
  assert.deepEqual(kept.map((r) => `${r.indicator}=${r.value}`), ['spo2=97', 'pulse=70', 'spo2=96', 'pulse=72']);
  let gone = false;
  const cuff = fakeBluetooth();
  const h2 = await ble.connectHealthDevice('blood-pressure', () => {}, { bluetooth: cuff, onDisconnect: () => { gone = true; } });
  assert.equal(h2.name, 'Test cuff');
  h2.disconnect();
  assert.equal(gone, true);
});

test('connectHealthDevice: closed chooser, no Bluetooth, a device without the measurement', async () => {
  assert.equal(await ble.connectHealthDevice('thermometer', () => {}, { bluetooth: fakeBluetooth({ refuse: 'NotFoundError' }) }), null);
  await assert.rejects(ble.connectHealthDevice('thermometer', () => {}, { bluetooth: null }), { name: 'NoBluetooth' });
  await assert.rejects(ble.connectHealthDevice('thermometer', () => {}, { bluetooth: fakeBluetooth({ has: [] }) }), /no standard thermometer measurement/);
  await assert.rejects(ble.connectHealthDevice('toaster', () => {}), /unknown device kind/);
});

// ---------- CSV ----------
test('parseCsv: quotes, separators, decimal commas, a byte order mark', () => {
  const a = csv.parseCsv('\uFEFFtime,note,value\r\n2026-11-14T06:00:00Z,"a, b ""c""",64\r\n');
  assert.deepEqual(a.columns, ['time', 'note', 'value']);
  assert.equal(a.rows[0].note, 'a, b "c"');
  const b = csv.parseCsv('Date;Time;LAeq\n14.11.2026;08:00;60,5\n');
  assert.equal(b.delimiter, ';');
  assert.equal(b.decimalComma, true);
  assert.equal(csv.toNumber(b.rows[0].LAeq, true), 60.5);
  assert.equal(csv.parseCsv('a\tb\n1\t2\n').delimiter, '\t');
});

test('parseTime: ISO, US and day-first dates, AM and PM, Hexoskin and Astroskin time bases', () => {
  assert.equal(new Date(csv.parseTime('2026-11-14T06:00:00+02:00')).toISOString(), '2026-11-14T04:00:00.000Z');
  assert.equal(new Date(csv.parseTime('2026-11-14 06:00')).toISOString(), '2026-11-14T06:00:00.000Z', 'no zone: GMT');
  assert.equal(new Date(csv.parseTime('10:45:00 PM', { date: '11/13/2026' })).toISOString(), '2026-11-13T22:45:00.000Z');
  assert.equal(new Date(csv.parseTime('12:10:00 AM', { date: '11/14/2026' })).toISOString(), '2026-11-14T00:10:00.000Z');
  assert.equal(new Date(csv.parseTime('08:00', { date: '03.04.2026', dayFirst: true })).toISOString(), '2026-04-03T08:00:00.000Z');
  assert.equal(new Date(csv.parseTime('25/12/2026 08:00')).toISOString(), '2026-12-25T08:00:00.000Z');
  // Hexoskin's own example: 390747224745 / 256 = 1526356347 s, 15 May 2018 03:52:27 GMT (rounded on their page).
  assert.ok(Math.abs(csv.parseTime('390747224745', { unit: 's/256' }) - Date.UTC(2018, 4, 15, 3, 52, 27)) < 1000);
  // Astroskin's own example: 1691371518000 is 7 August 2023 01:25:18 GMT.
  assert.equal(new Date(csv.parseTime('1691371518000', { unit: 's/1000' })).toISOString(), '2023-08-07T01:25:18.000Z');
  assert.ok(Number.isNaN(csv.parseTime('not a time')));
});

test('units: into the program\'s units, or refused', () => {
  assert.equal(csv.convertUnit('temp', 98.6, '°F').value, 37);
  assert.ok(Math.abs(csv.convertUnit('cabinPressure', 760, 'torr').value - 101.325) < 0.01);
  assert.equal(csv.convertUnit('sleep', 390, 'min').value, 6.5);
  assert.equal(csv.convertUnit('pulse', 70, 'bpm').value, 70);
  assert.match(csv.convertUnit('noise', 70, 'dB').error, /cannot turn/);
});

