function fakeFetch(answers) {
  const calls = [];
  const f = async (url, init = {}) => {
    calls.push({ url, body: init.body || '' });
    if (answers.fail) throw new TypeError('fetch failed');
    const op = /LS_op=destroy/.test(init.body || '') ? 'destroy' : url.split('?')[0].split('/').pop();
    const body = answers[op] ?? answers[url];
    if (body === undefined) return { ok: false, status: 404, text: async () => '', json: async () => null };
    return { ok: true, status: 200, text: async () => (typeof body === 'string' ? body : JSON.stringify(body)), json: async () => (typeof body === 'string' ? JSON.parse(body) : body) };
  };
  f.calls = calls;
  return f;
}

test('ISSLive: tonight\'s real answers become the ship\'s readings, stale CO2 and O2 marked with their age', async () => {
  const f = fakeFetch({ 'create_session.txt': fixture('isslive-create.txt'), 'control.txt': 'REQOK,1\r\n', 'bind_session.txt': fixture('isslive-bind.txt'), destroy: 'REQOK,2\r\n' });
  const r = await iss.readCabinAir({ fetch: f, now: () => new Date('2026-11-15T00:56:24Z') });
  assert.equal(r.ok, true);
  assert.equal(r.signal, 'acquired');
  const by = Object.fromEntries(r.readings.map((x) => [x.indicator, x]));
  assert.equal(by.cabinPressure.value, 101.05);
  assert.equal(by.cabinTemp.value, 23.3);
  assert.equal(by.co2.value, 2.44);
  assert.equal(by.cabinO2.value, 155.6);
  assert.equal(by.cabinPressure.stale, false);
  assert.equal(by.co2.stale, true);
  assert.equal(by.co2.time, '2026-11-02T15:01:08.004Z');
  assert.ok(r.readings.every((x) => x.source === 'isslive' && x.person === 'ship'));
  assert.equal(r.items.length, 7);
  const [create, sub, bind, destroy] = f.calls;
  assert.match(create.url, /create_session\.txt\?LS_protocol=TLCP-2\.4\.0$/);
  assert.match(create.body, /LS_adapter_set=ISSLIVE/);
  assert.match(create.body, /LS_cid=mgQkwtwdysogQz2BJ4Ji%20kOj2Bg/);
  assert.match(sub.body, /LS_mode=MERGE/);
  assert.match(sub.body, /LS_snapshot=true/);
  assert.match(sub.body, /LS_group=TIME_000001%20USLAB000058/);
  assert.match(bind.url, /bind_session\.txt/);
  assert.match(destroy.body, /LS_op=destroy/);
});

