const NOW = new Date('2026-11-15T01:00:00Z');
function flight() {
  const m = createMachine({ cells: CELLS, crew: [...CREW, SHIP], now: () => NOW });
  const tom = CREW[0];
  const add = (indicator, value, source, time, example = false) => m.receive({ person: tom.id, indicator, value, source, time, example });
  add('pulse', 64, 'ble-heart-rate', '2026-11-14T06:00:00Z');
  add('spo2', 97, 'oximeter', '2026-11-14T06:05:00Z', true);
  add('glucose', 92, 'manual', '2026-11-14T07:00:00Z');
  add('sleep', 6.71, 'csv-actiware', '2026-11-14T06:20:00Z');
  add('bp', { sys: 114, dia: 76 }, 'ble-bp', '2026-11-14T06:10:00Z');
  add('temp', 36.7, 'thermometer', '2026-11-14T06:15:00Z');
  add('fluid', 2600, 'drink-log', '2026-11-14T20:00:00Z');
  add('eyePressure', 15, 'tonometer', '2026-11-10T10:00:00Z');
  add('vo2max', 38, 'fitness-test', '2026-11-01T10:00:00Z');
  add('resp', 15, 'csv-hexoskin', '2026-11-14T06:30:00Z');
  add('pulse', 70, 'ble-heart-rate', '2026-09-01T06:00:00Z'); // older than 30 days
  m.receive({ person: SHIP.id, indicator: 'co2', value: 2.4, source: 'isslive', time: '2026-11-14T06:00:00Z' });
  return { m, tom };
}
let n = 0;
const counting = () => `00000000-0000-4000-8000-${String((n += 1)).padStart(12, '0')}`;
const res = (b, type) => b.entry.map((e) => e.resource).filter((r) => r.resourceType === type);
const obsBy = (b, code) => res(b, 'Observation').find((o) => o.code.coding[0].code === code);

test('FHIR: a well-formed collection, every reference resolves, unique urn:uuid entries', () => {
  const { m, tom } = flight();
  const { bundle, count } = fhir.fhirBundle({ machine: m, person: tom, now: NOW });
  assert.equal(bundle.resourceType, 'Bundle');
  assert.equal(bundle.type, 'collection');
  assert.deepEqual(fhir.checkBundle(bundle), []);
  assert.equal(count, 10);
  assert.equal(res(bundle, 'Patient').length, 1);
  assert.equal(res(bundle, 'Device').length, 9, 'every device-like origin, not the hand entry');
  assert.equal(res(bundle, 'Provenance').length, 10, 'one per origin');
  const urls = bundle.entry.map((e) => e.fullUrl);
  assert.equal(new Set(urls).size, urls.length);
  assert.ok(urls.every((u) => /^urn:uuid:[0-9a-f-]{36}$/.test(u)));
  const patientUrl = bundle.entry.find((e) => e.resource.resourceType === 'Patient').fullUrl;
  assert.ok(res(bundle, 'Observation').every((o) => o.subject.reference === patientUrl));
  assert.ok(!JSON.stringify(bundle).includes('urn:jff'), 'the old urn:jff names are gone');
  assert.ok(!JSON.stringify(bundle).includes('2026-09-01'), 'the period is respected');
  assert.ok(!JSON.stringify(bundle).includes('isslive'), 'cabin air is not in a person\'s record');
});

test('FHIR: the fixes of the night research (codes, categories, UCUM, sources of values)', () => {
  const { m, tom } = flight();
  const { bundle } = fhir.fhirBundle({ machine: m, person: tom, now: NOW, uuid: counting });
  assert.deepEqual(obsBy(bundle, '2708-6').code.coding.map((c) => c.code), ['2708-6', '59408-5']);
  const cat = (code) => (obsBy(bundle, code).category || []).map((c) => c.coding[0].code);
  assert.deepEqual(cat('8867-4'), ['vital-signs']);
  assert.deepEqual(cat('1556-0'), ['laboratory']);
  assert.deepEqual(cat('93832-4'), ['activity']);
  assert.deepEqual(cat('56844-4'), ['exam']);
  assert.deepEqual(cat('9108-2'), []);
  const bp = obsBy(bundle, '85354-9');
  assert.deepEqual(bp.component.map((c) => [c.code.coding[0].code, c.valueQuantity.value, c.valueQuantity.code]), [['8480-6', 114, 'mm[Hg]'], ['8462-4', 76, 'mm[Hg]']]);
  assert.deepEqual(obsBy(bundle, '8310-5').valueQuantity, { value: 36.7, unit: 'C', system: 'http://unitsofmeasure.org', code: 'Cel' });
  const pulse = obsBy(bundle, '8867-4');
  const device = bundle.entry.find((e) => e.fullUrl === pulse.device.reference).resource;
  assert.equal(device.deviceName[0].name, 'Bluetooth heart rate monitor');
  const glucose = obsBy(bundle, '1556-0');
  assert.equal(glucose.device, undefined, 'typed in: no device');
  assert.equal(glucose.performer[0].reference, glucose.subject.reference);
  const provFor = (o) => res(bundle, 'Provenance').find((p) => p.target.some((t) => bundle.entry.find((e) => e.fullUrl === t.reference).resource === o));
  assert.equal(provFor(glucose).agent[0].type.coding[0].code, 'enterer');
  assert.equal(provFor(pulse).agent[0].type.coding[0].code, 'author');
  assert.equal(provFor(obsBy(bundle, '93832-4')).entity[0].role, 'source', 'an imported file is named as the source');
  for (const l of fhir.LOINC_SOURCES) assert.match(l.url, /^https:\/\/clinicaltables\.nlm\.nih\.gov\//);
});

test('FHIR: HTEST on example and simulated values, and on everything with the example switch on', () => {
  const { m, tom } = flight();
  const plain = fhir.fhirBundle({ machine: m, person: tom, now: NOW }).bundle;
  const tagged = (r) => Boolean(r.meta && r.meta.security && r.meta.security.some((s) => s.code === 'HTEST'));
  assert.equal(tagged(obsBy(plain, '2708-6')), true, 'example reading');
  assert.equal(tagged(obsBy(plain, '8310-5')), true, 'a simulated button');
  assert.equal(tagged(obsBy(plain, '8867-4')), false, 'a real Bluetooth reading');
  assert.equal(tagged(res(plain, 'Patient')[0]), false);
  const ex = fhir.fhirBundle({ machine: m, person: tom, now: NOW, example: true }).bundle;
  assert.ok(tagged(ex) && tagged(res(ex, 'Patient')[0]) && res(ex, 'Observation').every(tagged));
  assert.ok(res(ex, 'Provenance').every((p) => p.reason && p.reason[0].coding[0].code === 'HTEST'));
});

